import assert from 'node:assert/strict';
import {writeFile,readFile,readdir,unlink,mkdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {createRequire} from 'node:module';
import {createServer} from 'node:http';
import {spawn} from 'node:child_process';
import {pathToFileURL} from 'node:url';
import {join} from 'node:path';
const require=createRequire(import.meta.url),sdk=await import(process.argv[2]),entry=process.argv[3],root=process.cwd(),config=await sdk.loadSettings(root),checks=[];
async function output(args,input){const child=spawn(process.execPath,args,{cwd:root,env:process.env,windowsHide:true,stdio:['pipe','pipe','pipe']});let out='',err='';child.stdout.on('data',s=>out+=s);child.stderr.on('data',s=>err+=s);child.stdin.end(input??'');const timer=setTimeout(()=>child.kill(),30000);try{const code=await new Promise((r,j)=>{child.once('error',j);child.once('close',r)});assert.equal(code,0,err+'\n'+out);return out}finally{clearTimeout(timer)}}
const cli=async args=>JSON.parse(await output([entry,...args,'--cwd',root]));
const vocab=join(root,'vocab.json'),ranks=require('js-tiktoken/ranks/cl100k_base'),bytes=JSON.stringify({bpe_ranks:ranks.bpe_ranks,special_tokens:{'<team>':200000},pat_str:ranks.pat_str});await writeFile(vocab,bytes);assert.equal(sdk.countPinnedTextTokens('<team>',{file:vocab,sha256:createHash('sha256').update(bytes).digest('hex'),patternEncoding:'custom',specialTokenMode:'allowed'}),1);checks.push('actual Node tokenizer child handles custom pattern and explicit private special tokens');
const benchmark=await cli(['context-benchmark','--tokens','1000000']);assert.equal(benchmark.ok,true);assert.equal(benchmark.measuredTokens,1000000);assert.equal(benchmark.modelRequests,0);checks.push('actual Node CLI measures 1M local BPE tokens without calling a model');
await mkdir(join(root,'launcher-deps'));await writeFile(join(root,'launcher-deps','known_hosts'),'fixture-key');await writeFile(join(root,'launcher'),'fixture executable');const binding=await sdk.bindLauncher(join(root,'launcher'),[join(root,'launcher-deps')]);assert.equal(binding.files.length,1);await writeFile(join(root,'launcher-deps','known_hosts'),'rotated-key');assert.notDeepEqual(await sdk.bindLauncher(join(root,'launcher'),[join(root,'launcher-deps')]),binding);checks.push('built launcher binding detects declared host-key/config changes');
let requests=0;const server=createServer(async(req,res)=>{let raw='';for await(const part of req)raw+=part;const body=JSON.parse(raw);requests++;assert.equal(body.stream,true);res.writeHead(200,{'Content-Type':'text/event-stream'});for(const delta of ['JOURNAL_','OK'])res.write(`data: ${JSON.stringify({type:'response.output_text.delta',delta})}\n\n`);res.end(`data: ${JSON.stringify({type:'response.completed',response:{id:'resp_journal',status:'completed',output:[{type:'message',role:'assistant',content:[{type:'output_text',text:'JOURNAL_OK'}]}],usage:{input_tokens:10,output_tokens:5}}})}\n\n`)});await new Promise(r=>server.listen(0,'127.0.0.1',r));
let selected;
try{Object.assign(config.model,{apiProtocol:'responses',provider:'openai',baseUrl:`http://127.0.0.1:${server.address().port}/v1`,apiKeyEnv:'',maxContextTokens:16000,maxOutputTokens:64,thinkingEnabled:false});config.hooks=[];config.network={allowedHosts:['127.0.0.1'],rejectUnauthorized:true,timeoutMs:5000};config.runtimeReplay={mode:'verbatim',acknowledgement:'I_ACCEPT_LOCAL_PLAINTEXT_TRANSCRIPTS'};await writeFile(join(root,'.ccpt/settings.json'),JSON.stringify(config));
 const result=await cli(['-p','Hello','--tools','read_file','--output-format','json']);assert.equal(result.result,'JOURNAL_OK');selected=result.session_id;assert(selected);const replay=await cli(['sessions','replay',selected,'--include-text','--limit','500']);assert.deepEqual(replay.items.filter(r=>r.type==='text_delta').map(r=>r.text),['JOURNAL_','OK']);assert.equal(replay.captureFailure,false);checks.push('actual compiled print worker persists exact explicit plaintext delta boundaries');
 await unlink(join(process.env.CCPT_HOME,'runtime-replay',selected+'.jsonl.index.json'));const rpc=JSON.parse((await output([entry,'ide','serve','--cwd',root],JSON.stringify({id:1,method:'runtime/replay',params:{id:selected,includeText:true,limit:500}})+'\n')).trim());assert.equal(rpc.result.items.filter(r=>r.type==='text_delta').length,2);assert.equal(requests,1);checks.push('restarted actual Node IDE bridge recovers a lost index and replays without model/tool execution');
 const before=await readdir(join(process.env.CCPT_HOME,'runtime-replay'));const ephemeral=await cli(['-p','Hello','--tools','read_file','--no-session-persistence','--output-format','json']);assert.equal(ephemeral.result,'JOURNAL_OK');assert.deepEqual(await readdir(join(process.env.CCPT_HOME,'runtime-replay')),before);checks.push('ephemeral compiled CLI does not capture or modify the opt-in journal');
 const code=`Object.defineProperty(process.stdin,'isTTY',{value:true});Object.defineProperty(process.stdout,'isTTY',{value:true});Object.defineProperty(process.stdout,'columns',{value:120});Object.defineProperty(process.stdout,'rows',{value:42});process.stdin.setRawMode=()=>process.stdin;process.argv=['node',${JSON.stringify(entry)},'--cwd',${JSON.stringify(root)}];await import(${JSON.stringify(pathToFileURL(entry).href)});`;
 const tui=spawn(process.execPath,['--input-type=module','-e',code],{cwd:root,env:process.env,windowsHide:true,stdio:['pipe','pipe','pipe']});let screen='',error='';tui.stdout.on('data',s=>screen+=s);tui.stderr.on('data',s=>error+=s);const until=Date.now()+20000;const wait=async f=>{while(Date.now()<until){if(f())return;await new Promise(r=>setTimeout(r,30))}throw new Error(error+screen.slice(-1500))};
 try{await wait(()=>screen.includes('CCPT'));tui.stdin.write(`/replay ${selected} --include-text\r`);await wait(()=>screen.includes('JOURNAL_'));tui.stdin.write('/exit\r');await new Promise((r,j)=>{const timer=setTimeout(()=>j(new Error('TUI exit timeout')),5000);tui.once('close',()=>{clearTimeout(timer);r()})});assert.equal(requests,2);checks.push('actual Node pipe-backed TTY /replay displays saved events without a model request')}finally{tui.kill()}
}finally{await new Promise(r=>server.close(r))}
console.log(JSON.stringify({pass:true,version:sdk.cli.CLI_VERSION,runtime:'actual compiled Node CLI/SDK/IDE/worker and pipe-backed TTY harness',checks,benchmark,modelRequests:requests,companyRequests:0,businessPushOrPR:false,osRegistrations:0,personalSettingsModified:false}));
